Save this as `index.html` and open it in a browser. It uses only the Three.js core ES module and includes direct mouse/touch camera controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Ball-and-Stick Water Molecule</title>

  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system,
        BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 50% 40%, #14283a 0%, #08131f 45%, #03070d 100%);
    }

    #scene {
      position: fixed;
      inset: 0;
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    #scene:active {
      cursor: grabbing;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background: radial-gradient(
        ellipse at center,
        transparent 45%,
        rgba(0, 0, 0, 0.38) 100%
      );
    }

    .title-card {
      position: fixed;
      top: 24px;
      left: 26px;
      z-index: 2;
      pointer-events: none;
      color: #eef7ff;
      text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55);
    }

    .eyebrow {
      margin-bottom: 7px;
      color: #6ee7ff;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(25px, 4vw, 42px);
      font-weight: 650;
      letter-spacing: -0.04em;
    }

    .subtitle {
      margin-top: 7px;
      color: rgba(220, 235, 248, 0.62);
      font-size: 13px;
    }

    .badge {
      position: fixed;
      top: 28px;
      right: 28px;
      z-index: 2;
      display: inline-flex;
      align-items: center;
      gap: 9px;
      padding: 9px 13px;
      border: 1px solid rgba(118, 231, 255, 0.2);
      border-radius: 999px;
      background: rgba(7, 19, 31, 0.64);
      color: #bff7ff;
      font-size: 12px;
      font-weight: 650;
      letter-spacing: 0.02em;
      pointer-events: none;
      backdrop-filter: blur(10px);
    }

    .badge::before {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #4de3ff;
      box-shadow: 0 0 12px #4de3ff;
      content: "";
    }

    .help {
      position: fixed;
      right: 25px;
      bottom: 22px;
      z-index: 2;
      color: rgba(213, 232, 246, 0.48);
      font-size: 11px;
      letter-spacing: 0.03em;
      pointer-events: none;
    }

    button {
      position: fixed;
      right: 25px;
      bottom: 58px;
      z-index: 3;
      padding: 9px 13px;
      border: 1px solid rgba(154, 210, 238, 0.2);
      border-radius: 9px;
      background: rgba(10, 24, 37, 0.72);
      color: #dcecf8;
      font: inherit;
      font-size: 11px;
      cursor: pointer;
      backdrop-filter: blur(10px);
    }

    button:hover {
      border-color: rgba(118, 231, 255, 0.5);
      background: rgba(18, 43, 61, 0.85);
    }

    .atom-label {
      position: fixed;
      z-index: 2;
      display: flex;
      align-items: center;
      gap: 7px;
      color: #e9f3fb;
      font-size: 12px;
      font-weight: 650;
      pointer-events: none;
      transform: translate(-50%, -50%);
      white-space: nowrap;
    }

    .atom-label::before {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      box-shadow: 0 0 10px currentColor;
      content: "";
    }

    #oxygen-label {
      color: #ff6175;
    }

    #oxygen-label::before {
      background: #ff6175;
      box-shadow: 0 0 10px #ff6175;
    }

    #hydrogen-label {
      color: #f4f8fc;
    }

    #hydrogen-label::before {
      background: #f4f8fc;
      box-shadow: 0 0 10px #f4f8fc;
    }

    @media (max-width: 600px) {
      .title-card {
        top: 18px;
        left: 18px;
      }

      .badge {
        top: auto;
        right: 18px;
        bottom: 62px;
      }

      .help {
        right: 18px;
        bottom: 18px;
      }

      .subtitle {
        max-width: 210px;
        line-height: 1.5;
      }
    }
  </style>
</head>

<body>
  <canvas id="scene" aria-label="Interactive 3D ball-and-stick water molecule"></canvas>
  <div class="vignette"></div>

  <div class="title-card">
    <div class="eyebrow">Molecular Structure</div>
    <h1>Water · H₂O</h1>
    <div class="subtitle">Ball-and-stick model with a 104° H–O–H bond angle</div>
  </div>

  <div class="badge">104° bond angle</div>

  <div id="oxygen-label" class="atom-label">O</div>
  <div id="hydrogen-label-left" class="atom-label">H</div>
  <div id="hydrogen-label-right" class="atom-label">H</div>

  <button id="reset-view" type="button">Reset view</button>
  <div class="help">Drag to orbit · Scroll or pinch to zoom</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const canvas = document.querySelector("#scene");
    const oxygenLabel = document.querySelector("#oxygen-label");
    const hydrogenLabelLeft = document.querySelector("#hydrogen-label-left");
    const hydrogenLabelRight = document.querySelector("#hydrogen-label-right");

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight, false);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.15;

    const scene = new THREE.Scene();

    const camera = new THREE.PerspectiveCamera(
      38,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    // Lighting
    scene.add(new THREE.HemisphereLight(0xc5e5ff, 0x071019, 1.6));

    const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
    keyLight.position.set(3.5, 5, 4.5);
    scene.add(keyLight);

    const rimLight = new THREE.PointLight(0x328dff, 12, 12, 2);
    rimLight.position.set(-3.5, 1.5, -2.5);
    scene.add(rimLight);

    const warmLight = new THREE.PointLight(0xff6b83, 5, 8, 2);
    warmLight.position.set(2, -2, 1);
    scene.add(warmLight);

    // Molecule geometry
    const molecule = new THREE.Group();
    scene.add(molecule);

    const oxygenPosition = new THREE.Vector3(0, 0, 0);

    // The included H–O–H angle is exactly 104 degrees.
    const halfBondAngle = THREE.MathUtils.degToRad(52);
    const bondLength = 1;
    const hydrogenPosition = new THREE.Vector3(
      Math.sin(halfBondAngle) * bondLength,
      Math.cos(halfBondAngle) * bondLength,
      0
    );

    const oxygenMaterial = new THREE.MeshPhysicalMaterial({
      color: 0xff3f62,
      roughness: 0.26,
      metalness: 0.04,
      clearcoat: 0.75,
      clearcoatRoughness: 0.22
    });

    const hydrogenMaterial = new THREE.MeshStandardMaterial({
      color: 0xf4f8fc,
      roughness: 0.32,
      metalness: 0.02
    });

    const bondMaterial = new THREE.MeshStandardMaterial({
      color: 0x8796a3,
      roughness: 0.48,
      metalness: 0.18
    });

    const sleeveMaterial = new THREE.MeshStandardMaterial({
      color: 0x647483,
      roughness: 0.42,
      metalness: 0.24
    });

    const yAxis = new THREE.Vector3(0, 1, 0);

    function createMesh(geometry, material) {
      const mesh = new THREE.Mesh(geometry, material);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      molecule.add(mesh);
      return mesh;
    }

    function cylinderBetween(start, end, radius, material, radialSegments = 16) {
      const direction = new THREE.Vector3().subVectors(end, start);
      const length = direction.length();

      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        radialSegments,
        1,
        false
      );

      const mesh = createMesh(geometry, material);

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(yAxis, direction.normalize());

      return mesh;
    }

    // Main oxygen atom
    const oxygen = createMesh(
      new THREE.SphereGeometry(0.38, 48, 32),
      oxygenMaterial
    );
    oxygen.position.copy(oxygenPosition);

    // Main hydrogen atoms
    const hydrogenGeometry = new THREE.SphereGeometry(0.205, 32, 24);
    const leftHydrogen = createMesh(hydrogenGeometry, hydrogenMaterial);
    const rightHydrogen = createMesh(hydrogenGeometry, hydrogenMaterial);

    leftHydrogen.position.copy(hydrogenPosition);
    rightHydrogen.position.copy(hydrogenPosition.clone().negate());

    // Bond directions away from the oxygen atom.
    const leftBondDirection = hydrogenPosition.clone().normalize();
    const rightBondDirection = hydrogenPosition
      .clone()
      .negate()
      .normalize();

    // Gray cylindrical bonds.
    cylinderBetween(
      oxygenPosition.clone().addScaledVector(leftBondDirection, 0.2),
      leftHydrogen.position.clone().addScaledVector(leftBondDirection, -0.2),
      0.052,
      bondMaterial
    );

    cylinderBetween(
      oxygenPosition.clone().addScaledVector(rightBondDirection, 0.2),
      rightHydrogen.position.clone().addScaledVector(rightBondDirection, -0.2),
      0.052,
      bondMaterial
    );

    // Shallow sleeves at the oxygen ends.
    const leftOxygenSleeve = createMesh(
      new THREE.CylinderGeometry(0.315, 0.315, 0.3, 24),
      sleeveMaterial
    );
    leftOxygenSleeve.position.copy(
      oxygenPosition.clone().addScaledVector(leftBondDirection, 0.25)
    );
    leftOxygenSleeve.quaternion.setFromUnitVectors(
      yAxis,
      leftBondDirection
    );

    const rightOxygenSleeve = createMesh(
      new THREE.CylinderGeometry(0.315, 0.315, 0.3, 24),
      sleeveMaterial
    );
    rightOxygenSleeve.position.copy(
      oxygenPosition.clone().addScaledVector(rightBondDirection, 0.25)
    );
    rightOxygenSleeve.quaternion.setFromUnitVectors(
      yAxis,
      rightBondDirection
    );

    // Shallow sleeves surrounding each hydrogen atom.
    const leftHydrogenSleeve = createMesh(
      new THREE.CylinderGeometry(0.19, 0.19, 0.28, 24),
      sleeveMaterial
    );
    leftHydrogenSleeve.position.copy(
      leftHydrogen.position.clone().addScaledVector(leftBondDirection, -0.23)
    );
    leftHydrogenSleeve.quaternion.setFromUnitVectors(yAxis, leftBondDirection);

    const rightHydrogenSleeve = createMesh(
      new THREE.CylinderGeometry(0.19, 0.19, 0.28, 24),
      sleeveMaterial
    );
    rightHydrogenSleeve.position.copy(
      rightHydrogen.position.clone().addScaledVector(rightBondDirection, -0.23)
    );
    rightHydrogenSleeve.quaternion.setFromUnitVectors(yAxis, rightBondDirection);

    // Direct camera controls, implemented without external addons.
    const target = new THREE.Vector3(0, 0.48, 0);

    const defaultView = {
      radius: 5.15,
      theta: 0.18,
      phi: 1.34
    };

    const desired = { ...defaultView };
    const current = { ...defaultView };

    let dragging = false;
    let previousX = 0;
    let previousY = 0;
    let activePointers = new Map();
    let pinchDistance = 0;

    function updateCamera() {
      const spherical = new THREE.Spherical(
        current.radius,
        current.phi,
        current.theta
      );

      camera.position.setFromSpherical(spherical).add(target);
      camera.lookAt(target);
    }

    function resetView() {
      desired.radius = defaultView.radius;
      desired.theta = defaultView.theta;
      desired.phi = defaultView.phi;
    }

    canvas.addEventListener("pointerdown", (event) => {
      activePointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (activePointers.size === 1) {
        dragging = true;
        previousX = event.clientX;
        previousY = event.clientY;
        canvas.setPointerCapture(event.pointerId);
      } else if (activePointers.size === 2) {
        const points = [...activePointers.values()];
        pinchDistance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!activePointers.has(event.pointerId)) return;

      activePointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (activePointers.size === 2) {
        const points = [...activePointers.values()];
        const distance = Math.hypot(
          points[0].x - points[1].x,
          points[0].y - points[1].y
        );

        if (pinchDistance > 0) {
          desired.radius = THREE.MathUtils.clamp(
            desired.radius * (pinchDistance / distance),
            3.2,
            9
          );
        }

        pinchDistance = distance;
        return;
      }

      if (!dragging) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;

      previousX = event.clientX;
      previousY = event.clientY;

      desired.theta -= deltaX * 0.006;
      desired.phi = THREE.MathUtils.clamp(
        desired.phi - deltaY * 0.006,
        0.35,
        Math.PI - 0.35
      );
    });

    function endPointer(event) {
      activePointers.delete(event.pointerId);

      if (activePointers.size < 2) {
        pinchDistance = 0;
      }

      if (activePointers.size === 0) {
        dragging = false;
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);
    canvas.addEventListener("lostpointercapture", endPointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();

        desired.radius = THREE.MathUtils.clamp(
          desired.radius * Math.exp(event.deltaY * 0.001),
          3.2,
          9
        );
      },
      { passive: false }
    );

    document.querySelector("#reset-view").addEventListener("click", resetView);

    // Project labels from 3D positions into screen space.
    const projected = new THREE.Vector3();

    function positionLabel(element, worldPosition) {
      projected.copy(worldPosition).project(camera);

      const visible = projected.z > -1 && projected.z < 1;
      element.style.opacity = visible ? "1" : "0";

      if (!visible) return;

      const x = (projected.x * 0.5 + 0.5) * window.innerWidth;
      const y = (-projected.y * 0.5 + 0.5) * window.innerHeight;

      element.style.left = `${x}px`;
      element.style.top = `${y}px`;
    }

    function onResize() {
      const width = window.innerWidth;
      const height = window.innerHeight;

      camera.aspect = width / height;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(width, height, false);
    }

    window.addEventListener("resize", onResize);

    const clock = new THREE.Clock();

    renderer.setAnimationLoop(() => {
      const delta = Math.min(clock.getDelta(), 0.05);
      const damping = 1 - Math.exp(-8 * delta);

      current.radius = THREE.MathUtils.lerp(
        current.radius,
        desired.radius,
        damping
      );

      current.theta = THREE.MathUtils.lerp(
        current.theta,
        desired.theta,
        damping
      );

      current.phi = THREE.MathUtils.lerp(
        current.phi,
        desired.phi,
        damping
      );

      updateCamera();

      positionLabel(oxygenLabel, oxygenPosition);
      positionLabel(hydrogenLabelLeft, leftHydrogen.position);
      positionLabel(hydrogenLabelRight, rightHydrogen.position);

      renderer.render(scene, camera);
    });

    updateCamera();
  </script>
</body>
</html>
```
